"""Original poems; figurative comparisons are literary choices, not scientific claims."""
def author(E,C,O):
 S='plan-G3-literature-07'
 E(S,'S1','A','소리를 담은 골목',
 '시: 골목의 아침\n철컥, 가게 문이 눈을 뜨고\n달그락, 빈 병들이 인사를 한다\n내 운동화도 또각또각\n골목의 아침에 한 소절을 보탠다\n감각적 표현은 소리, 빛깔, 냄새, 맛, 닿는 느낌 등을 떠올리게 한다. 이 시의 철컥과 달그락은 소리를 떠올리게 한다. 한 소절을 보탠다는 말은 발소리가 골목의 여러 소리에 더해지는 모습을 노래에 빗댄 표현이다.',
 '실제 소리와 시의 표현을 구별하되 흉내말만 감각적 표현이라고 한정하지 않는다. 낭송은 선택 활동이며 읽기 답안만으로 낭송 수행을 판정하지 않는다.',[
 C('달그락이 주로 떠올리게 하는 감각은 무엇인가요?','빈 병들이 내는 소리','철컥과 달그락을 소리 표현으로 설명하고 병들이라는 대상을 제시했다.',[('병에 밴 달콤한 냄새','냄새를 나타내는 말이 아니다.'),('병 표면의 매끄러운 촉감','손으로 만지는 느낌이 아니다.'),('병 속 음료의 새콤한 맛','음료나 맛이 시에 제시되지 않았다.')],'빈 병들이 인사를'),
 O('classification','철컥 / 또각또각을 소리가 나는 대상과 연결하세요.','철컥:가게 문 / 또각또각:운동화',['철컥, 가게 문','내 운동화도 또각또각'],'한 대상만 맞게 연결함','두 소리를 모두 병 소리라고 함'),
 O('explanation','한 소절을 보탠다는 표현에서 발소리와 골목의 다른 소리는 어떤 관계인가요?','내 발소리도 골목의 여러 소리에 더해져 함께 노래하는 것처럼 느껴진다.','발소리가 골목의 여러 소리에','소리가 난다는 점만 적음','운동화가 실제로 노래를 부른다고 설명함')])
 E(S,'S2','A','비가 그친 평상',
 '시: 젖은 나무 평상\n빗방울이 떠난 자리\n짙어진 나뭇결이 길게 누웠다\n손바닥에 서늘한 물기가 묻고\n젖은 나무 냄새가 천천히 올라온다\n나는 마른 끝자리를 찾아 앉는다',
 '시각·촉각·후각 단서를 직접 찾는다. 젖은 곳이 언제나 같은 냄새라는 외부 사실로 일반화하지 않는다.',[
 C('손으로 닿는 느낌을 직접 나타낸 부분은 무엇인가요?','손바닥에 서늘한 물기가 묻고','손바닥과 서늘한 물기는 닿는 감각을 직접 드러낸다.',[('짙어진 나뭇결이 길게 누웠다','빛깔과 모양을 보는 표현이다.'),('젖은 나무 냄새가 천천히 올라온다','후각을 나타내는 표현이다.'),('나는 마른 끝자리를 찾아 앉는다','자리 선택 행동이며 서늘한 촉감을 직접 표현하지 않는다.')],'손바닥에 서늘한'),
 O('matching','나뭇결의 짙은 빛깔 / 서늘한 물기 / 나무 냄새를 감각과 연결하세요.','빛깔:시각 / 물기:촉각 / 냄새:후각',['짙어진 나뭇결','서늘한 물기가','젖은 나무 냄새'],'세 감각 중 두 가지를 맞게 연결함','물기를 맛으로 분류함'),
 O('evidence_selection','비가 그친 뒤에도 물기가 남아 있음을 보여 주는 시구를 찾으세요.','손바닥에 서늘한 물기가 묻고','손바닥에 서늘한','빗방울이 떠났다는 부분만 써 남은 물기를 보이지 못함','마른 끝자리만 근거로 모든 곳이 말랐다고 함'),
 O('explanation','그냥 평상에 앉았다고 쓴 글과 달리, 이 시에서 구체적으로 떠올릴 수 있는 장면을 감각 표현 하나와 연결하세요.','서늘한 물기가 손에 묻는 표현 때문에 비 뒤에 아직 축축한 평상을 손으로 짚는 장면이 떠오른다. 다른 감각 근거도 수용한다.','손바닥에 서늘한','비 뒤 장면이라고만 하고 감각 표현 연결이 없음','마른 사막이라고 하며 시의 표현과 반대로 설명함')])
 E(S,'S3','A','두 가지 바람',
 '시 가: 점심 운동장\n바람이 모래알을 톡톡 굴린다\n빈 그네가 끼익 답한다\n팔을 벌린 내 셔츠가\n작은 돛처럼 부풀어 오른다\n시 나: 저녁 창가\n바람이 커튼 끝을 살짝 든다\n식은 찻잔 곁에서\n책장이 사르르 인사하고\n내 손은 다음 줄에 머문다',
 '바람이라는 공통 소재와 서로 다른 감각·움직임을 연결한다. 소리 크기를 실제 측정한 자료로 취급하지 않는다.',[
 C('두 시의 표현을 알맞게 연결한 것은 무엇인가요?','가는 셔츠를 돛에 빗대고 나는 책장 소리를 담았다.','가의 작은 돛처럼과 나의 사르르가 각각 비유와 소리의 근거다.',[('가는 커튼을 돛에 빗대고 나는 그네 소리를 담았다.','대상과 소리를 두 시 사이에서 바꿨다.'),('가는 책장 소리만 담고 나는 셔츠 움직임만 담았다.','각 시의 감각 대상이 뒤바뀌었다.'),('가는 돛의 실제 크기를 재고 나는 소리 높이를 쟀다.','두 시 모두 수치 측정이나 측정 행동을 제시하지 않는다.')],['작은 돛처럼 부풀어','책장이 사르르']),
 O('matching','가의 셔츠 / 나의 커튼이 바람 때문에 어떻게 움직이는지 연결하세요.','셔츠:부풀어 오름 / 커튼:끝이 살짝 들림',['셔츠가','커튼 끝을 살짝'],'한 움직임만 정확히 연결함','커튼이 모래알을 굴린다고 함'),
 O('explanation','셔츠와 작은 돛을 연결한 공통 모습을 쓰세요.','둘 다 바람을 받아 부풀어 오른 모습으로 연결된다.','작은 돛처럼 부풀어','모양이 비슷하다고만 하고 어떤 모양인지 없음','셔츠가 실제 배로 바뀌었다고 함'),
 O('explanation','바람이 똑같이 나오지만 두 시의 장면이 다르게 느껴지는 이유를 두 시구와 연결하세요.','가는 톡톡·끼익과 부푼 셔츠로 움직이는 운동장이, 나는 살짝 든 커튼과 사르르 책장으로 잔잔한 창가가 떠오른다. 다른 근거 있는 비교도 수용한다.',['빈 그네가 끼익','커튼 끝을 살짝'],'한 시의 표현만으로 비교함','실제 풍속 수치가 주어졌다고 설명함')])
 E(S,'S4','A','흰 새가 앉은 손등',
 '시: 밀가루 묻은 손\n반죽을 누르던 할머니 손등에\n흰 새 한 마리가 잠깐 앉았다\n손을 털자 새는 가볍게 날아가고\n햇빛 속에 작은 가루가 반짝였다\n나는 내 손등도 가만히 내밀었다',
 '새를 실제 동물로 단정하는 해석과 밀가루를 통한 비유 해석을 근거로 대조한다. 마지막 행동의 마음은 한 감정말로 고정하지 않는다.',[
 C('흰 새를 이해한 말로 가장 근거가 있는 것은 무엇인가요?','손등의 밀가루를 새처럼 표현했다.','제목의 밀가루, 손 털기, 날리는 가루가 흰 새라는 표현을 함께 뒷받침한다.',[('날아든 새를 할머니가 직접 길렀다.','새를 기르거나 실제 새가 들어온 사건은 제시되지 않는다.'),('반죽 안에 장난감 새를 숨겨 놓았다.','숨긴 장난감은 시에 없고 마지막에는 가루가 보인다.'),('손등에 흰 새 모양 그림을 완성했다.','그리는 행동이 없으며 손을 턴 뒤 가루가 반짝인다.')],['반죽을 누르던','손을 털자','작은 가루가 반짝였다']),
 O('evidence_selection','흰 새가 실제 새가 아닐 수 있음을 보여 주는 서로 다른 단서 두 개를 찾으세요.','밀가루 묻은 손이라는 제목 / 손을 턴 뒤 가루가 반짝임',['밀가루 묻은 손','작은 가루가 반짝였다'],'한 단서만 제시함','아무 이유 없이 실제 새는 없다고 함'),
 O('explanation','가루가 날아갔다 대신 새는 가볍게 날아갔다고 표현한 효과를 설명하세요.','가루가 가볍게 흩어지는 움직임을 새가 날아오르는 모습처럼 생생하게 떠올리게 한다.','새는 가볍게 날아가고','생생하다고만 하고 두 움직임을 연결하지 않음','가루가 정말 생명체로 변했다고 함'),
 O('explanation','마지막에 내 손등도 내민 행동에 어떤 마음이 담겼을지 앞 장면과 연결해 짐작하세요.','할머니 손의 흰 가루가 새처럼 날아가는 모습이 신기해 내 손에서도 보고 싶었을 수 있다. 함께 반죽하고 싶은 마음 등도 근거와 연결하면 수용한다.',['흰 새 한 마리가','내 손등도 가만히'],'신기하다고만 쓰고 앞 장면 연결이 없음','할머니와 싸우려 했다고 근거 없이 단정함')])
 E(S,'S5','A','꼭 슬픈 소리일까',
 '시: 문방구 가는 길\n낙엽이 운동화 밑에서 바스락\n얇은 주머니도 바스락\n주머니 속 접은 편지 한 장\n엄마에게 줄 봉투를 고르러\n나는 노란 가게 문을 민다\n독자 가는 바스락이 반복되니 말하는 이는 반드시 슬프다고 했다. 독자 나는 발밑과 주머니의 소리가 이어져 걸어가는 장면이 선명하다고 했다.',
 '시의 감정은 다양한 근거 있는 해석을 허용한다. 슬픔을 금지하는 것이 아니라 한 소리만으로 반드시라고 단정하는 범위를 검토한다.',[
 C('독자 가의 말에서 특히 따져 볼 부분은 무엇인가요?','같은 소리만으로 슬픔을 반드시 확정한 점','소리의 반복은 있지만 마음을 하나로 확정할 직접 진술은 없고 편지를 위한 행동도 함께 읽어야 한다.',[('발밑과 주머니에 비슷한 소리가 나는 점','그 소리의 반복 자체는 시에 제시되어 있다.'),('엄마에게 줄 봉투를 고르러 가는 점','그 목적은 시에서 직접 읽을 수 있다.'),('말하는 이가 가게 문을 미는 점','가게 문을 미는 행동은 마지막 행에 있다.')],'반드시 슬프다고'),
 O('evidence_selection','독자 나의 해석을 뒷받침하는 소리 표현 두 곳을 쓰세요.','낙엽이 운동화 밑에서 바스락 / 얇은 주머니도 바스락',['운동화 밑에서 바스락','얇은 주머니도 바스락'],'한 소리만 제시함','시와 무관한 쨍그랑을 근거로 듦'),
 O('explanation','독자 가를 고칠 때 슬프지 않다고 단정해도 되는지 설명하세요.','그렇게 반대로 단정할 근거도 부족하다. 바스락만으로 마음을 확정하지 말고 편지와 봉투를 고르는 행동까지 함께 살펴야 한다.',['주머니 속 접은 편지','봉투를 고르러'],'단정하면 안 된다고만 하고 읽을 다른 장면을 제시하지 못함','엄마가 나오면 언제나 기쁘다고 단정함'),
 O('revision','반드시 슬프다는 말을 근거에 맞는 해석으로 고치세요.','반복되는 바스락 소리가 걷는 장면을 생생하게 한다. 편지를 전할 마음은 다른 행동과 함께 짐작해야 한다. 다른 유보적인 해석도 수용한다.',['운동화 밑에서 바스락','나는 노란 가게 문을'],'반드시만 지우고 왜 고쳤는지 없음','슬픔이라는 해석은 어떤 경우에도 틀렸다고 바꿈'),
 O('explanation','자신이 느낀 분위기를 소리나 행동 두 곳과 연결해 설명하세요.','바스락 소리가 이어지고 봉투를 고르러 문을 미는 행동이 있어 편지를 준비하는 설렘으로 느꼈다. 다른 근거 있는 분위기도 수용한다.',['얇은 주머니도 바스락','노란 가게 문을'],'분위기와 근거 한 곳만 연결함','분위기 말만 쓰고 작품과 관계가 없음')])
 E(S,'S6','A','비슷한 빛을 다른 장면으로',
 '자료 가, 시: 작은 부엌\n저녁 햇살 한 조각이\n빈 그릇 바닥에 고여 있다\n아빠가 국자를 내려놓자\n그릇 속 해도 동그랗게 흔들린다\n자료 나, 시: 버스 창\n유리창에 저녁빛이 번진다\n지나가는 간판마다\n붉은 물결이 한 번씩 접히고\n내 무릎 위 그림책에도 닿는다\n새 쓰기 상황. 저녁빛이 들어오는 현관에서 젖은 신발을 벗는 장면을 쓴다. 두 시의 문장을 복사하지 말고 빛깔이나 닿는 느낌을 골라 표현한다.',
 '시의 비유와 감각을 새 상황에서 활용하되 예시 답을 모범 문장으로 외우게 하지 않는다. 작품 감상과 자기 표현을 각각 확인한다.',[
 C('두 시가 저녁빛을 표현한 방식을 알맞게 비교한 것은 무엇인가요?','가는 그릇에 고인 해로, 나는 접히는 물결로 그렸다.','그릇 속 해와 붉은 물결은 각 시의 빛을 형상화한 표현이다.',[('가는 실제 해를 그릇에 넣고 나는 실제 물을 버스에 쏟았다.','비유를 물리적인 사건으로 바꿔 읽었다.'),('가는 버스의 간판을, 나는 부엌의 국자를 그렸다.','두 작품의 대상과 배경을 바꿨다.'),('가는 빛의 온도를 재고 나는 햇빛의 무게를 쟀다.','두 시에 측정 과정과 수치가 없다.')],['그릇 속 해도','붉은 물결이']),
 O('matching','고여 있다 / 접히고를 각각 어느 장면의 빛과 연결했는지 쓰세요.','고여 있다:그릇 바닥의 저녁 햇살 / 접히고:간판을 지나며 보이는 붉은 저녁빛',['빈 그릇 바닥에 고여','지나가는 간판마다'],'한 표현만 장면과 연결함','두 표현을 실제 물이 든 장면이라고 함'),
 O('explanation','두 시 중 더 선명하게 떠오른 장면 하나를 표현과 연결해 설명하세요.','그릇 속 해가 흔들린다는 표현 때문에 그릇 바닥의 둥근 빛이 움직이는 부엌 장면이 떠올랐다. 나의 장면을 근거 있게 골라도 수용한다.',['동그랗게 흔들린다','붉은 물결이'],'선택은 하지만 구체적인 시구나 장면이 없음','작품에 없는 밤바다만 설명함'),
 O('writing','새 현관 장면을 감각적 표현이 들어간 두세 줄로 쓰세요.','젖은 양말이 발끝을 서늘하게 잡는다. 신발 옆으로 귤빛 길이 길게 누웠다. 다른 적절한 표현도 수용한다.','저녁빛이 들어오는 현관','현관 장면은 있지만 감각이 드러나는 표현이 없음','두 원시를 그대로 복사해 현관 장면이 없음'),
 O('explanation','자신이 쓴 감각 표현이 어떤 느낌이나 모습을 떠올리게 하는지 설명하세요.','서늘하게 잡는다는 말로 젖은 양말이 발에 닿는 느낌을 떠올리게 했다. 자신의 실제 표현을 설명하면 수용한다.','빛깔이나 닿는 느낌을 골라','감각의 이름만 말하고 자기 표현과 연결하지 않음','자기가 쓰지 않은 표현만 설명함'),
 O('revision','자신의 초고에서 한 부분을 고쳐 쓰고 장면이 어떻게 달라졌는지 쓰세요.','빛이 있다를 귤빛 길이 길게 누웠다로 고쳐 빛깔과 길게 드리운 모양을 드러냈다. 다른 타당한 수정도 수용한다.','두 시의 문장을 복사하지','표현은 고쳤지만 달라진 장면을 설명하지 못함','띄어쓰기만 바꾸고 감각 표현 수정이라고 함')])
